SELECT COUNT(DISTINCT OBSERVATION_ID) AS nebula_count
FROM JWST.ANALYTICS.V_OBSERVATION_TAGS
WHERE LOWER(TAG) = 'nebula';

SELECT CATEGORY_NAME
FROM JWST.ANALYTICS.V_OBSERVATIONS
GROUP BY CATEGORY_NAME
HAVING COUNT(*) = (
    SELECT MAX(cnt) FROM (
        SELECT COUNT(*) AS cnt
        FROM JWST.ANALYTICS.V_OBSERVATIONS
        GROUP BY CATEGORY_NAME
    )
);

SELECT COUNT(*) AS observations_with_tags FROM (
    SELECT OBSERVATION_ID
    FROM JWST.ANALYTICS.V_OBSERVATION_TAGS
    GROUP BY OBSERVATION_ID
    HAVING COUNT(TAG) >= 1
) sub;
